import pathlib,json,hashlib,importlib.util,collections,numpy as np,zipfile,csv,io,bisect,datetime,ast
R=pathlib.Path(r'C:\tmp\disdex-d126-crossrunner-research-20261126');F=R/'Y06_BINANCE_FUNDING_20261127'
SRC=R/'y06_r3_bear_retest_research_v2.py';prior=R/'Y06_R15_BINANCE_NORMALIZED_RESULTS_20261127.json';feat=R/'Y06_R16_DERIVATIVES_FEATURES_20261127.json'
