bt=r3.bt;H=bt.H;M=bt.M
P=R/'Y06_R16_DERIVATIVES_BT_PROTOCOL_20261127.json';O=R/'Y06_R16_DERIVATIVES_BT_RESULTS_20261127.json';assert not P.exists() and not O.exists()
p={'status':'RESEARCH_ONLY_POST_HOC_EXPLORATION','parents':{x.name:hashlib.sha256(x.read_bytes()).hexdigest() for x in (prior,feat,F/'manifest.json')},'base_tapes':['ASTER_H1','ASTER','BINANCE_CONT_M5','BINANCE_NORM_M5'],'features':'OI6h and long-short account ratio from Binance metrics >=5 minutes prior; depth +/-1% notional imbalance >=1 min prior, funding last settled rate strictly prior with age <=12h. Funding archives through Oct2026 so November unavailable. No imputation.','gates':{'BASE':'no new gate','OI_RISE':'asset OI6>0','OI_FALL':'asset OI6<0','OI_RISE2':'asset OI6>=.02','BTC_OI_RISE':'BTC OI6>0','LS_LONG':'global account L/S>1','FUND_POS':'last settled Binance funding>0','FUND_NEG':'last settled Binance funding<0','DEPTH_ASK':'bid-ask depth imbalance<=-.1','DEPTH_BID':'imbalance>=.1','OI_RISE_LS_LONG':'asset OI6>0 and LS>1','OI_RISE_FUND_POS':'asset OI6>0 and last funding>0','OI_RISE_ASK':'asset OI6>0 and depth<=-.1'},'exits':'H24, H48, H48 TP8; STOP8 conservative gap. Original wallet .30x per position 2 slots and 12h cooldown, 10/30bps. Compare each gate to same feature-available cohort, not unrestricted baseline. No actual liquidation events.','control':'For each gate arm/ex with 3 positive periods and >=8 admitted trades per period, 32 fixed-seed random thinning of available original tape, matched by UTC calendar month and candidate count. Zero control sample means no claim. Selection post R15; not untouched.','scope':'Fund rate feature only where archived; no OI/board fictional reconstruction. Actual funding PnL sensitivity separately R15 target proxy; no production.'}
P.write_text(json.dumps(p,indent=2),encoding='utf8')
d=json.loads(prior.read_text());fd=json.loads(feat.read_text());lookup={(x['symbol'],x['entryTs']):x for x in fd['features']};ms={}
for sym in bt.SYMS[1:]:
 m,_=bt.data(sym,'5m');ms[sym]=m;print('LOAD',sym,flush=True)
fmap={}
for sym in bt.SYMS[1:]:
 a=[]
 for fn in sorted(F.glob(sym+'USDT-fundingRate-*.zip')):
  with zipfile.ZipFile(fn) as z:
   for row in csv.DictReader(io.StringIO(z.read(z.namelist()[0]).decode('utf-8-sig'))):
    a.append((int(row['calc_time']),float(row['last_funding_rate'])))
 a.sort();fmap[sym]=([x[0] for x in a],a)
def lastfund(x):
 ts,a=fmap[x['symbol']];j=bisect.bisect_left(ts,x['entryTs'])-1
 return a[j][1] if j>=0 and x['entryTs']-ts[j]<=12*H else None
def endof(per):return bt.PERIODS[per][1] if per!='FORWARD_INSPECTED' else bt.T('2026-11-26T00:00:00Z')
src=(R/'y06_r14_binance_cross_venue_20261127.py').read_text();tr=ast.parse(src)
exec(compile(ast.Module(body=[x for x in tr.body if isinstance(x,ast.FunctionDef) and x.name in ('trade','compact')],type_ignores=[]),str(R/'y06_r14_binance_cross_venue_20261127.py'),'exec'))
def flags(x):
 f=lookup.get((x['symbol'],x['entryTs']),{});a=f.get('asset');b=f.get('btc');q=f.get('depth');fr=lastfund(x)
 oi=None if a is None else a['oi6'];ls=None if a is None else a['ls_ratio'];boi=None if b is None else b['oi6'];dep=None if q is None else q['imbalance']
 return {'BASE':True,'OI_RISE':None if oi is None else oi>0,'OI_FALL':None if oi is None else oi<0,'OI_RISE2':None if oi is None else oi>=.02,'BTC_OI_RISE':None if boi is None else boi>0,'LS_LONG':None if ls is None else ls>1,'FUND_POS':None if fr is None else fr>0,'FUND_NEG':None if fr is None else fr<0,'DEPTH_ASK':None if dep is None else dep<=-.1,'DEPTH_BID':None if dep is None else dep>=.1,'OI_RISE_LS_LONG':None if oi is None or ls is None else oi>0 and ls>1,'OI_RISE_FUND_POS':None if oi is None or fr is None else oi>0 and fr>0,'OI_RISE_ASK':None if oi is None or dep is None else oi>0 and dep<=-.1}
def mon(t):return datetime.datetime.fromtimestamp(t/1000,datetime.timezone.utc).strftime('%Y-%m')
rng=np.random.default_rng(2026112716);out={};coverage={}
for name in p['base_tapes']:
 xx=list({(x['symbol'],x['entryTs']):x for x in d['tapes'][name]}.values());ff=[(x,flags(x)) for x in xx]
 coverage[name]={g:{'available':sum(v[g] is not None for x,v in ff),'pass':sum(v[g] is True for x,v in ff)} for g in p['gates']}
 print('COVER',name,json.dumps(coverage[name]),flush=True)
 for hr,tp in ((24,0),(48,0),(48,.08)):
  ex=str(hr)+('_TP8' if tp else '');alltr=[(z,v) for x,v in ff if (z:=trade(x,hr,tp)) is not None]
  for gate in p['gates']:
   if gate.startswith('DEPTH') or gate=='OI_RISE_ASK':
    if name!='ASTER_H1':continue
   key=name+'/'+gate+'/'+ex;out[key]={};coh={}
   for per in bt.PERIODS:
    a=[z for z,v in alltr if z['period']==per and v[gate] is not None];b=[z for z,v in alltr if z['period']==per and v[gate] is True];coh[per]=(a,b)
    w={str(f):compact(bt.wallet(b,per,f,ms)) for f in (10,30)};base=compact(bt.wallet(a,per,30,ms))
    out[key][per]={'available':len(a),'selected':len(b),'wallet':w,'available_baseline30':base}
   vs=[v['wallet']['30'] for v in out[key].values()]
   if gate=='BASE' or all(x['terminal_jpy']>10000 for x in vs):print('BT',key,[(round(x['terminal_jpy']),round(x['max_dd_pct'],2),x['n'],x['wins']) for x in vs],flush=True)
   if gate=='BASE' or not all(x['terminal_jpy']>10000 and x['n']>=8 for x in vs):continue
   for per,(a,b) in coh.items():
    groups=collections.defaultdict(list);n=collections.Counter(mon(z['entryTs']) for z in b)
    for z in a:groups[mon(z['entryTs'])].append(z)
    draws=[]
    for _ in range(32):
     z=[groups[m][int(i)] for m,k in n.items() for i in rng.choice(len(groups[m]),size=k,replace=False)]
     draws.append(compact(bt.wallet(z,per,30,ms)))
    actual=out[key][per]['wallet']['30'];vs=[z['terminal_jpy'] for z in draws]
    out[key][per]['random_thinning']={'mean':float(np.mean(vs)),'beats':sum(actual['terminal_jpy']>v for v in vs),'draws':draws}
    print('MATCH',key,per,round(actual['terminal_jpy']),round(np.mean(vs)),out[key][per]['random_thinning']['beats'],flush=True)
O.write_text(json.dumps({'protocol':p,'protocol_sha256':hashlib.sha256(P.read_bytes()).hexdigest(),'coverage':coverage,'results':out},indent=2,allow_nan=False),encoding='utf8')
print('SAVED',hashlib.sha256(O.read_bytes()).hexdigest(),flush=True)

