import pathlib,json,hashlib,urllib.request,zipfile,io,csv,datetime,collections,concurrent.futures
R=pathlib.Path(r'C:\tmp\disdex-d126-crossrunner-research-20261126')
src=R/'Y06_R15_BINANCE_NORMALIZED_RESULTS_20261127.json'
out=R/'Y06_R16_DERIVATIVES_FEATURES_20261127.json'
assert not out.exists()
d=json.loads(src.read_text());arms=['ASTER','ASTER_H1','BINANCE_CONT_M5','BINANCE_NORM_M5','ASTER_BINANCE_NOT_BULL']
samples={(x['symbol'],x['entryTs']):x for a in arms for x in d['tapes'][a]}
book_samples={(x['symbol'],x['entryTs']) for x in d['tapes']['ASTER_H1']}
# one archived daily file per unique required date, only the samples needed; store full zip for metrics, only compact rows+SHA for depth.
B=R/'Y06_BINANCE_METRICS_20261127';B.mkdir(exist_ok=True)
def day(t):return datetime.datetime.fromtimestamp(t/1000,datetime.timezone.utc).strftime('%Y-%m-%d')
tasks=collections.defaultdict(set)
for s,t in samples:
 for sym in (s,'BTC'):
  for dt in {day(t-300000),day(t-6*3600000-300000)}:tasks[('metrics',sym,dt)].add(t)
for s,t in book_samples:tasks[('bookDepth',s,day(t-60000))].add(t)
def fetch(item):
 (kind,s,dt),times=item;sy=s+'USDT';name=f'{sy}-{kind}-{dt}.zip';p=B/name;url=f'https://data.binance.vision/data/futures/um/daily/{kind}/{sy}/{name}'
 try:
  if kind=='metrics' and p.exists():b=p.read_bytes()
  else:
   with urllib.request.urlopen(url,timeout=15) as res:b=res.read(12000000)
  z=zipfile.ZipFile(io.BytesIO(b));data=z.read(z.namelist()[0]).decode('utf-8-sig')
  if kind=='metrics' and not p.exists():p.write_bytes(b)
  rr=csv.DictReader(io.StringIO(data));res=[]
  if kind=='metrics':
   for row in rr:
    t=int(datetime.datetime.fromisoformat(row['create_time']).replace(tzinfo=datetime.timezone.utc).timestamp()*1000)
    vals=[float(row[k]) for k in ('sum_open_interest','count_long_short_ratio','sum_taker_long_short_vol_ratio')]
    if vals[0]>0 and vals[1]>=0 and vals[2]>=0:res.append([t,*vals])
   # retain only 5m snapshots needed for the requested timestamps (max one prior point, 15min lag)
   res.sort();filtered={}
   for t in times:
    for q in (t-300000,t-6*3600000-300000):
     a=[v for v in res if q-900000<=v[0]<=q]
     if a:filtered[str(q)]=a[-1]
  else:
   rows=collections.defaultdict(dict)
   for row in rr:
    try: pct=float(row['percentage'])
    except ValueError:continue
    if pct not in (-1.,1.):continue
    t=int(datetime.datetime.fromisoformat(row['timestamp']).replace(tzinfo=datetime.timezone.utc).timestamp()*1000)
    rows[t][pct]=float(row['notional'])
   good=sorted((t,v[-1.],v[1.]) for t,v in rows.items() if -1. in v and 1. in v and v[-1.]>=0 and v[1.]>=0 and v[-1.]+v[1.]>0)
   filtered={}
   for t in times:
    q=t-60000;a=[v for v in good if q-300000<=v[0]<=q]
    if a:filtered[str(t)]=a[-1]
  return {'key':[kind,s,dt],'status':'OK','sha256':hashlib.sha256(b).hexdigest(),'bytes':len(b),'features':filtered}
 except Exception as e:return {'key':[kind,s,dt],'status':'ERROR','error':str(e),'features':{}}
print('TASKS',len(tasks),'SAMPLES',len(samples),'BOOK_SAMPLES',len(book_samples),flush=True)
with concurrent.futures.ThreadPoolExecutor(max_workers=8) as pool:
 results=[]
 for v in pool.map(fetch,sorted(tasks.items())):
  results.append(v)
  if len(results)%100==0:print('PROGRESS',len(results),sum(x['status']=='OK' for x in results),flush=True)
lookup={(v['key'][0],v['key'][1],v['key'][2]):v['features'] for v in results}
def metric(s,t):
 q=t-300000;prior=q-6*3600000
 a=lookup.get(('metrics',s,day(q)),{}).get(str(q));b=lookup.get(('metrics',s,day(prior)),{}).get(str(prior))
 if a is None or b is None:return None
 return {'time':a[0],'prior_time':b[0],'oi6':a[1]/b[1]-1,'ls_ratio':a[2],'taker_ratio':a[3]}
features=[]
for (s,t),x in samples.items():
 b=lookup.get(('bookDepth',s,day(t-60000)),{}).get(str(t));features.append({'symbol':s,'entryTs':t,'asset':metric(s,t),'btc':metric('BTC',t),'depth':None if b is None else {'time':b[0],'imbalance':(b[1]-b[2])/(b[1]+b[2]),'bid_notional':b[1],'ask_notional':b[2]}})
out.write_text(json.dumps({'status':'RESEARCH_ONLY','parent_sha256':hashlib.sha256(src.read_bytes()).hexdigest(),'source':'Binance data.vision metrics daily and bookDepth daily; metrics >=5m delay, depth >=1m delay; no interpolation; missing fail closed; exact candidate times frozen by prior experiment','manifest':results,'features':features},indent=2),encoding='utf8')
print('DONE',len(results),sum(v['status']=='OK' for v in results),'ASSET',sum(v['asset'] is not None for v in features),'BTC',sum(v['btc'] is not None for v in features),'BOOK',sum(v['depth'] is not None for v in features),'SHA',hashlib.sha256(out.read_bytes()).hexdigest(),flush=True)
